1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Inventory\Domain\Model;
6	
7	use App\Inventory\Domain\Exception\InsufficientStockException;
8	use App\Inventory\Domain\Exception\NothingReservedException;
9	use App\Inventory\Domain\ValueObject\Reservation;
10	use App\Ordering\Domain\ValueObject\OrderId;
11	use App\Ordering\Domain\ValueObject\ProductId;
12	use App\SharedKernel\Domain\AggregateRoot;
13	use Doctrine\ORM\Mapping as ORM;
14	
15	#[ORM\Entity]
16	#[ORM\Table(name: 'stock_items')]
17	final class StockItem extends AggregateRoot
18	{
19	    /**
20	     * Rezervace podle objednávky: ID objednávky => počet kusů.
21	     *
22	     * @var array<string, int>
23	     */
24	    #[ORM\Column(type: 'json')]
25	    private array $reservations = [];
26	
27	    public function __construct(
28	        #[ORM\Id]
29	        #[ORM\Column(type: 'product_id')]
30	        public readonly ProductId $productId,
31	        #[ORM\Column]
32	        public private(set) int $onHand,
33	    ) {
34	        if ($onHand < 0) {
35	            throw new \InvalidArgumentException('Stock on hand cannot be negative');
36	        }
37	    }
38	
39	    /** Kusy, které jde ještě rezervovat. */
40	    public function available(): int
41	    {
42	        return $this->onHand - $this->reserved();
43	    }
44	
45	    public function reserved(): int
46	    {
47	        return array_sum($this->reservations);
48	    }
49	
50	    public function reserve(OrderId $orderId, int $quantity): void
51	    {
52	        if ($quantity < 1) {
53	            throw new \InvalidArgumentException('Reserved quantity must be positive');
54	        }
55	
56	        // INVARIANT: rezervace nepřesáhne zásobu.
57	        if ($quantity > $this->available()) {
58	            throw InsufficientStockException::forProduct($this->productId, $quantity, $this->available());
59	        }
60	
61	        $this->reservations[$orderId->value] = ($this->reservations[$orderId->value] ?? 0) + $quantity;
62	    }
63	
64	    public function release(OrderId $orderId): void
65	    {
66	        // INVARIANT: uvolnit jde jen to, co je rezervované.
67	        if (!$this->hasReservationFor($orderId)) {
68	            throw NothingReservedException::forOrder($this->productId, $orderId);
69	        }
70	
71	        unset($this->reservations[$orderId->value]);
72	    }
73	
74	    public function hasReservationFor(OrderId $orderId): bool
75	    {
76	        return isset($this->reservations[$orderId->value]);
77	    }
78	
79	    /** @return list<Reservation> */
80	    public function reservations(): array
81	    {
82	        $reservations = [];
83	        foreach ($this->reservations as $orderId => $quantity) {
84	            $reservations[] = new Reservation(OrderId::fromString($orderId), $quantity);
85	        }
86	
87	        return $reservations;
88	    }
