25	    {
26	        $itemsTotal = 0;
27	        $discounts = 0;
28	        $paid = 0;
29	        foreach ($orders as $order) {
30	            if ($order->currency !== $currency) {
31	                continue;
32	            }
33	            $itemsTotal += $order->totalAmount()->amountInCents;
34	            $discounts += $order->discount->amountInCents;
35	            $paid += $order->paidAmount()->amountInCents;
36	        }
37	
38	        return new self(
39	            count($orders),
40	            new Money($itemsTotal, $currency),
41	            new Money($discounts, $currency),
42	            new Money($paid, $currency),
43	        );
44	    }
45	
