50	     */
51	    public static function sumOf(array $amounts, Currency $currency = Currency::CZK): Money
52	    {
53	        $sum = 0;
54	        foreach ($amounts as $amount) {
55	            $sum += $amount->amountInCents;
56	        }
57	
58	        return new Money($sum, $currency);
