1	<?php
2	/**
3	 * Most mezi Symfony a starou administraci (2024).
4	 *
5	 * Symfony routa /admin/legacy/{page} -> __invoke(). Stara administrace cte
6	 * superglobalni promenne, takze sem prekopirujeme query/post z Requestu,
7	 * spustime controller nebo proceduralni stranku pod ob_start() a vystup
8	 * vratime jako Response.
9	 *
10	 * Jedine misto v src/Legacy, ktere zna Symfony.
11	 */
12	
13	namespace App\Legacy\Http;
14	
15	use App\Legacy\Admin\AdminController;
16	use App\Legacy\Admin\CustomerController;
17	use App\Legacy\Admin\ExportController;
18	use App\Legacy\Admin\InvoiceController;
19	use App\Legacy\Admin\OrderController;
20	use App\Legacy\Admin\ProductController;
21	use App\Legacy\Admin\ReportController;
22	use App\Legacy\Admin\StockController;
23	use App\Legacy\Admin\UserController;
24	use App\Legacy\lib\AccessDenied;
25	use Symfony\Component\HttpFoundation\Request;
26	use Symfony\Component\HttpFoundation\Response;
27	use Symfony\Component\Messenger\Exception\HandlerFailedException;
28	use Symfony\Component\Messenger\MessageBusInterface;
29	use Symfony\Component\Messenger\Stamp\HandledStamp;
30	use Symfony\Component\Security\Core\User\UserInterface;
31	use Symfony\Component\Security\Http\Attribute\CurrentUser;
32	
33	class LegacyFrontController
34	{
35	    public function __construct(
36	        // vychozi sbernice je command.bus (config/packages/messenger.yaml)
37	        private MessageBusInterface $commandBus,
38	    ) {
39	    }
40	
41	    /**
42	     * Role Symfony uzivatele -> role stare administrace (admin_users.role).
43	     * Prvni nalezena vyhrava; personal bez nich smi jen stranky s auth_require() bez role.
44	     */
45	    private static $roles = array(
46	        'ROLE_ADMIN'  => 'admin',
47	        'ROLE_OBCHOD' => 'obchod',
48	        'ROLE_UCETNI' => 'ucetni',
49	        'ROLE_SKLAD'  => 'sklad',
50	    );
51	
52	    /**
53	     * Povolene stranky: page => array(trida, metoda) nebo nazev souboru v Admin/.
54	     */
55	    private static $pages = array(
56	        // "MVC" controllery (2017+)
57	        'dashboard'          => array(AdminController::class, 'dashboardAction'),
58	        'search'             => array(AdminController::class, 'searchAction'),
59	        'report'             => array(ReportController::class, 'monthlyAction'),
60	        'report_year'        => array(ReportController::class, 'yearAction'),
61	        'report_top'         => array(ReportController::class, 'topAction'),
62	        'orders'             => array(OrderController::class, 'listAction'),
63	        'order'              => array(OrderController::class, 'detailAction'),
64	        'customer_orders'    => array(OrderController::class, 'byCustomerAction'),
65	        'customers'          => array(CustomerController::class, 'listAction'),
66	        'customer'           => array(CustomerController::class, 'detailAction'),
67	        'customer_delete'    => array(CustomerController::class, 'deleteAction'),
68	        'customer_anonymize' => array(CustomerController::class, 'anonymizeAction'),
69	        'products'           => array(ProductController::class, 'listAction'),
70	        'products_bulk_price'=> array(ProductController::class, 'bulkPriceAction'),
71	        'product_toggle'     => array(ProductController::class, 'toggleAction'),
72	        'stock'              => array(StockController::class, 'listAction'),
73	        'stock_reservations' => array(StockController::class, 'reservationsAction'),
74	        'stock_inventory'    => array(StockController::class, 'inventoryAction'),
75	        'user_list'          => array(UserController::class, 'listAction'),
76	        'user_save'          => array(UserController::class, 'saveAction'),
77	        'user_delete'        => array(UserController::class, 'deleteAction'),
78	        'invoices'           => array(InvoiceController::class, 'listAction'),
79	        'invoice'            => array(InvoiceController::class, 'detailAction'),
80	        'invoice_issue'      => array(InvoiceController::class, 'issueAction'),
81	        'export'             => array(ExportController::class, 'indexAction'),
82	        'export_csv'         => array(ExportController::class, 'ordersAction'),
83	        'export_customers'   => array(ExportController::class, 'customersAction'),
84	
85	        // proceduralni stranky (2014–2016)
86	        'order_edit'         => 'order_edit.php',
87	        'orders_bulk'        => 'orders.php',
88	        'order_list'         => 'order_list.php',
89	        'order_notes'        => 'order_notes.php',
90	        'unpaid_orders'      => 'unpaid_orders.php',
91	        'users'              => 'users.php',
92	        'login'              => 'login.php',
93	        'logout'             => 'logout.php',
94	        'stats'              => 'stats.php',
95	        'chart'              => 'chart.php',
96	        'monthly'            => 'monthly.php',
97	        'customer_edit'      => 'customer_edit.php',
98	        'customer_export'    => 'customer_export.php',
99	        'product_edit'       => 'product_edit.php',
100	        'newsletter'         => 'newsletter.php',
101	        'settings'           => 'settings.php',
102	        'audit'              => 'audit.php',
103	        'invoice_print'      => 'invoice_print.php',
104	        'stock_report'       => 'stock_report.php',
105	        'top_products'       => 'top_products.php',
106	        'suppliers'          => 'suppliers.php',
107	        'exchange_rates'     => 'exchange_rates.php',
108	        'sales_by_currency'  => 'sales_by_currency.php',
109	
110	        // akce, ktere meni objednavku prikazem noveho e-shopu (2026)
111	        'order_item_quantity'=> array(OrderController::class, 'changeItemQuantityAction'),
112	    );
113	
114	    public function __invoke(Request $request, string $page = 'dashboard', #[CurrentUser] ?UserInterface $user = null): Response
115	    {
116	        require_once __DIR__ . '/../bootstrap.php';
117	
118	        if (!isset(self::$pages[$page])) {
119	            return new Response('<h1>404</h1><p>Stránka neexistuje.</p>', 404);
120	        }
121	
122	        // stara administrace cte superglobaly
123	        $_GET = $request->query->all();
124	        $_POST = $request->request->all();
125	        $_REQUEST = array_merge($_GET, $_POST);
126	        $_SERVER['REQUEST_METHOD'] = $request->getMethod();
127	
128	        // prihlaseny uzivatel pro auth_user()/auth_require() a token pro csrf_check()
129	        $GLOBALS['LEGACY_USER'] = $user === null ? null : self::legacyUser($user);
130	        $GLOBALS['LEGACY_CSRF_TOKEN'] = self::csrfToken($request);
131	
132	        $GLOBALS['LEGACY_REDIRECT'] = null;
133	        $GLOBALS['LEGACY_STATUS'] = 200;
134	        $GLOBALS['LEGACY_CONTENT_TYPE'] = 'text/html; charset=utf-8';
135	        $GLOBALS['LEGACY_FILENAME'] = null;
136	
137	        // prikazy noveho e-shopu, stara administrace je vola pres legacy_command()
138	        $GLOBALS['LEGACY_COMMAND'] = function ($command) {
139	            try {
140	                $envelope = $this->commandBus->dispatch($command);
141	            } catch (HandlerFailedException $e) {
142	                // stara administrace chyta domenove vyjimky, ne obalku Messengeru
143	                $wrapped = $e->getWrappedExceptions();
144	                throw $wrapped ? reset($wrapped) : $e;
145	            }
146	            $handled = $envelope->last(HandledStamp::class);
147	
148	            return $handled !== null ? $handled->getResult() : null;
149	        };
150	
151	        $target = self::$pages[$page];
152	        $level = ob_get_level();
153	        ob_start();
154	        try {
155	            if (is_array($target)) {
156	                $controller = new $target[0]();
157	                $result = call_user_func(array($controller, $target[1]));
158	                $html = ob_get_clean() . (is_string($result) ? $result : '');
159	            } else {
160	                $this->includePage(__DIR__ . '/../Admin/' . $target);
161	                $html = ob_get_clean();
162	            }
163	        } catch (AccessDenied $e) {
164	            // auth_require() nebo csrf_check(); driv die()
165	            return new Response('<h1>403</h1><p>' . htmlspecialchars($e->getMessage(), ENT_QUOTES, 'UTF-8') . '</p>', 403);
166	        } finally {
167	            while (ob_get_level() > $level) {
168	                ob_end_clean();
169	            }
170	            // uzivatel a token patri jen tomuto pozadavku
171	            unset($GLOBALS['LEGACY_USER'], $GLOBALS['LEGACY_CSRF_TOKEN']);
172	        }
173	
174	        if (!empty($GLOBALS['LEGACY_REDIRECT'])) {
175	            return new Response('', 302, array('Location' => $GLOBALS['LEGACY_REDIRECT']));
176	        }
177	
178	        $response = new Response($html, (int) $GLOBALS['LEGACY_STATUS']);
179	        $response->headers->set('Content-Type', $GLOBALS['LEGACY_CONTENT_TYPE']);
180	        if (!empty($GLOBALS['LEGACY_FILENAME'])) {
181	            $response->headers->set('Content-Disposition', 'attachment; filename="' . $GLOBALS['LEGACY_FILENAME'] . '"');
182	        }
183	
184	        return $response;
185	    }
186	
187	    /**
188	     * Symfony uzivatel ve tvaru radku admin_users, jak ho cte auth_user().
189	     */
190	    private static function legacyUser(UserInterface $user)
191	    {
192	        $role = '';
193	        foreach (self::$roles as $symfonyRole => $legacyRole) {
194	            if (in_array($symfonyRole, $user->getRoles(), true)) {
195	                $role = $legacyRole;
196	                break;
197	            }
198	        }
199	
200	        return array('id' => null, 'login' => $user->getUserIdentifier(), 'role' => $role);
201	    }
202	
203	    /**
204	     * Jeden CSRF token na session (viz lib/csrf.php).
205	     */
206	    private static function csrfToken(Request $request)
207	    {
208	        $session = $request->getSession();
209	        $token = $session->get('legacy_csrf_token');
210	        if (!is_string($token) || $token === '') {
211	            $token = bin2hex(random_bytes(32));
212	            $session->set('legacy_csrf_token', $token);
213	        }
214	
215	        return $token;
216	    }
217	
218	    /**
219	     * Include ve vlastnim scope, at si stranky neprepisuji promenne mostu.
220	     */
221	    private function includePage($file)
222	    {
223	        include $file;
224	    }
225	}
